- Ẹ̀san wọn wà ní ọ̀dọ̀ Olúwa wọn; kò sì sí ìbẹ̀rù lórí wọn, bẹ́ẹ̀ ni wọn kì yóò sì ṣèdánù. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:62; 2:262; 2:274; 2:277
- Àwọn tí ó gbàgbọ́ tí wọn sì ṣe iṣẹ́ rere, ni a ó fí wọ àwọn Ọgbà Ọ̀run tí àwọn odò ń ṣàn ní abẹ́ wọn. (وَأُدْخِلَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 14:23; 22:14; 22:23; 47:12
- Ó sọ pé: "Ẹ̀yin ènìyàn mi! Ẹ sin Allāh; ẹ kò ní ọlọ́run mìíràn yàtọ̀ sí un. Ṣé ẹ kò?" (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23
- Ọrọ̀ wọn àti àwọn ọmọ wọn kì yóò ṣe wọn láǹfààní kan nítorí Allāh; àwọn yẹn sì ni. (لَن تُغْنِيَ عَنْهُمْ أَمْوَالُهُمْ وَلَا أَوْلَادُهُم مِّنَ اللَّهِ شَيْئًا وَأُولَئِكَ) 3:10; 3:116; 58:17
- Ọgbà Ọ̀run tí àwọn odò ń ṣàn ní abẹ́ wọn, wọn yóò máa gbé inú rẹ̀ láéláé, ìyẹn sì ni àṣeyọrí ńlá. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ الْفَوْزُ الْعَظِيمُ) 4:13; 9:89
- Ṣé àkọsọ́ àwọn tí ó ṣáájú wọn kò dé ọ̀dọ̀ wọn – àwọn ènìyàn Núh, àti 'Aad, àti Thamud? (أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ) 9:70; 14:9
- Ta ni àwọn olùrànlọ́wọ́ mi sí ọ̀nà Allāh? Àwọn ọmọ-ẹ̀yìn sọ pé: "Àwa ni olùrànlọ́wọ́ Allāh, àwa gbàgbọ́." (مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ آمَنَّا) 3:52; 61:14
- Olúwa rẹ ni Ó mọ̀ ju ẹnikẹ́ni lọ nípa ẹni tí ó ṣìnà kúrò lójú ọ̀nà Rẹ̀, Ó sì mọ̀ ju ẹnikẹ́ni lọ nípa àwọn tí a mọ̀nà. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 16:125; 68:7
- Ìyẹn jẹ́ nítorí pé Allāh ni Òtítọ́, àti pé ohun tí wọn ń pe lẹ́yìn Rẹ̀ jẹ́ asán. (ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ) 22:62; 31:30
- Ẹnikẹ́ni tí ó ṣe ìgbọràn sí Allāh àti Ojúṣe Rẹ̀, Òun yóò fí wọ Ọgbà Ọ̀run tí àwọn odò ń ṣàn ní abẹ́ wọn. (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- Ó ti há èèwọ̀ fún yín nípa ẹran òkú, ẹ̀jẹ̀, ẹran ẹlẹ́dẹ̀, àti ohun tí a pa (fún ẹlòmíràn). (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- Wí pé ẹ má ṣe sin ẹnikẹ́ni yàtọ̀ sí Allāh. Dájúdájú, èmi ń bẹ̀rù fún yín ìyà ọjọ́ kan. (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- Ìyẹn jẹ́ ara àwọn ìtàn ìkọ̀kọ̀ tí a fi í ṣe ìfihàn fún ọ; ìwọ kò sí lọ́dọ̀ wọn nígbà náà. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- Ṣé ẹ̀ ń ṣe kàyéfì pé ìránnilétí kan ti wá sí ọ̀dọ̀ yín láti ọ̀dọ̀ Olúwa yín nípasẹ̀ ọkùnrin kan láàrín yín láti kìlọ̀ fún yín? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- Sọ pé: "Dájúdájú, a ti kọ̀ mí ni láti sin àwọn tí ẹ̀ ń pe lẹ́yìn Allāh." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- Àyàfi àwọn aya wọn tàbí ohun tí ọwọ́ ọ̀tún wọn ní – dájúdájú àwọn kì í ṣe ẹni ìbáwí. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- Nítorí Allāh ń mú òru wọ inú ọ̀sán, ó sì ń mú ọ̀sán wọ inú òru. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- Iná, ó sọ fún ẹbí rẹ̀: "Ẹ dúró; mo ri iná kan; bóyá èmi yóò mú ohun kan wá fún yín láti inú rẹ̀." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- Ó sọ pé: "Èmi sàn ju òun lọ; Ìwọ dá mi láti inú iná, òun sì dá òun láti inú amọ̀." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- Nígbà tí a bá sọ fún wọn: "Ẹ wá sí ohun tí Allāh ti sọ̀kalẹ̀ àti sí Ọ̀ràn," wọn ń sọ. (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- Má ṣe kábínú fún wọn, má sì ṣe wà nínú ṣúfị́ nítorí ohun tí wọn ń dìmọ̀. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- Bí Allāh bá fọwọ́ kan ọ pẹ̀lú ìpọ́njú, kò sí ẹni tí ó lè yọ́ kúrò láfi àfi Òun; bí ó bá sì. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- Ṣáájú wọn, àwọn ìran tí ń rìn kiri ní àwọn ibùgbé wọn. Dájúdájú, àwọn àmì wà nínú ìyẹn. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- A sì ti fi ìbórí sí ọkàn wọn kí wọn má bàa lóye rẹ̀, àti ní etí wọn ìdiwo, bí wọn bá. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- Àwọn Ojúṣe wọn dé bá wọn pẹ̀lú ẹ̀rí kedere; ṣùgbọ́n Allāh kì í ṣe ẹni tí ń ṣe àwọn ẹ̀ṣẹ̀, ṣùgbọ́n àwọn fúnra wọn ni wọn ń ṣe àwọn ẹ̀ṣẹ̀. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- Àti lórí ilẹ̀, ẹ kò sì ní alágbátọ kan tàbí olùrànlọ́wọ́ kan yàtọ̀ sí Allāh. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- Lẹ́yìn náà, a ó yín padà sí Ọ̀pẹ̀lẹ̀ ohun ìkọ̀kọ̀ àti ohun gbangba; nígbà náà ni Òun yóò sọ fún yín ohun tí ẹ̀ ń ṣe. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- Òru kí ẹ lè sinmi nínú rẹ̀, àti ọ̀sán láti ríran. Dájúdájú, àwọn àmì wà nínú ìyẹn fún ènìyàn. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- Èyí yóò sì mú ọ̀pọ̀lọpọ̀ wọn nínú ohun tí a sọ̀kalẹ̀ fún ọ láti ọ̀dọ̀ Olúwa rẹ pọ̀ si nínú ìdìtẹ̀ àti àìgbàgbọ́. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- Ó sọ pé: "Ẹ̀yin ènìyàn mi! Ẹ rí i bí èmi bá wà lórí ẹ̀rí kedere láti ọ̀dọ̀ Olúwa mi, tí ó sì fún mi ní?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- Wọn sì ń sọ pé: "Kí ló dé tí a kò fi ran àmì kan sí i láti ọ̀dọ̀ Olúwa rẹ̀?" Sọ pé: "Dájúdájú." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- Ṣáájú kí ọjọ́ kan tí kò sí ìdápadà rẹ̀ láti ọ̀dọ̀ Allāh tó dé. (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- Ìyẹn ni oore Allāh tí Òun ń fúnni ẹni tí ó bá fẹ́; Allāh sì ni Ọlọ́run oore ńlá. (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- Dájúdájú, àwọn ẹran ọ̀sìn ní ẹ̀kọ́ kan fún yín; a ń mu yín nínú ohun tí ó wà nínú ikùn wọn. (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- Pé òtítọ́ ni láti ọ̀dọ̀ Olúwa wọn; Allāh kì í sì í ṣe aláìbìkítà fún ohun tí wọn ń ṣe. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- Níwájú wọn àti lẹ́yìn wọn, pé ẹ má ṣe sin ẹnikẹ́ni yàtọ̀ sí Allāh. (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- Dájúdájú, ẹ̀ ń tọ́ àwọn ọkùnrin lọ pẹ̀lú ìfẹ́kúfẹ̀ẹ́ dípò àwọn obìnrin; dípò bẹ́ẹ̀, ẹ̀yin jẹ́ ènìyàn. (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- Wọn yóò máa gbé inú rẹ̀ láéláé, níwọ̀n bí àwọn ọ̀run àti ilẹ̀ bá ṣì wà, àyàfi ohun tí Olúwa rẹ fẹ́. (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- Ẹni tí ó wà ní àwọn ọ̀run àti ẹni tí ó wà lórí ilẹ̀, àyàfi ẹni tí Allāh fẹ́. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- Wọn yóò fi ọ̀ṣọ́ àgbálákà wúrà àti ègún ṣe wọn lọ́ṣọ̀ọ́ inú rẹ̀, aṣọ wọn sì jẹ́ aṣọ aláṣọ. (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
- Ó si rọ̀ omi láti ọ̀run, ó si fi í mú èso jáde gẹ́gẹ́ bí oúnjẹ fún yín. (وَأنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ) 2:22; 14:32
- Nígbà tí a mú májẹ̀mú yín, tí a sì gbé òkè sókè lórí yín: "Ẹ mú ohun tí a fún yín pẹ̀lú agbára." (وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ) 2:63; 2:93
