- Láàrín wọn ni Ọjọ́ Àjínkí, nipa ohun tí wọn ń ṣe àríyànjiyàn. (بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 10:93; 16:124; 22:69; 32:25; 45:17
- Ṣebí wọn kò rìn kiri lórí ilẹ̀ lati wo bí òpin ... ṣe rí? (أَوَلَمْ يَسِيرُوا فِي الْأَرْضِ فَيَنظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 30:9; 35:44; 40:21; 40:82; 47:10
- Àwọn ọgbà Ọ̀run tí àwọn odò ń ṣàn ní abẹ́ wọn, wọn yóò máa gbé inú rẹ̀ láéláé. (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 5:119; 64:9; 65:11
- O ń fi òru bọ́ inú ọ̀sán, o sì ń fi ọ̀sán bọ́ inú òru. (تُولِجُ اللَّيْلَ فِي النَّهَارِ وَتُولِجُ النَّهَارَ فِي اللَّيْلِ) 3:27; 22:61; 31:29; 35:13; 57:6
- Gbogbo ohun tí ó wà ní àwọn ọ̀run àti gbogbo ohun tí ó wà lórí ilẹ̀ ń ṣogo fún Allah. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 59:1; 61:1; 62:1; 64:1
- Ẹ sin Allah, ẹ kò ní ọlọ́run mìíràn yàtọ̀ sí Un. Ṣebí ẹ kò ni lẹ́rù? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا) 7:65; 11:84; 23:23; 23:32
- Nigbati A sọ fún àwọn Mọlaika pe: "Ẹ tẹríba fún Adamu," wọn sì tẹríba, àyàfi Iblisi. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ) 2:34; 17:61; 18:50; 20:116
- Allah mọ ohun tí ó wà ní àwọn ọ̀run àti ohun tí ó wà lórí ilẹ̀. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 3:29; 5:97; 49:16; 58:7
- Àwọn ọgbà Ọ̀run tí àwọn odò ń ṣàn ní abẹ́ wọn, wọn yóò máa gbé inú rẹ̀ láéláé, ati pe iyen... (جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ) 4:13; 5:85; 9:89; 57:12
- Èrè rẹ̀ wà ní ọ̀dọ̀ Olúwa rẹ̀, bẹ́ẹ̀ ni kò sí ìbẹ̀rù fún wọn, bẹ́ẹ̀ ni wọn kì yóò... (أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:112; 2:262; 2:274; 2:277
- Ní ọ̀dọ̀ Olúwa rẹ̀, bẹ́ẹ̀ ni kò sí ìbẹ̀rù fún wọn, bẹ́ẹ̀ ni wọn kì yóò ṣọ̀fọ̀. (عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ) 2:112; 2:262; 2:274; 2:277
- Ẹnikẹ́ni tí ó bá gba ìmọ̀nà, ohun tí ó gbà fún ara rẹ̀ ni, àti ẹni tí ó bá ṣì... (فَمَنِ اهْتَدَى فَإِنَّمَا يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ) 10:108; 17:15; 27:92
- Ohun tí ó gbà fún ara rẹ̀ ni; àti ẹni tí ó bá ṣì, ohun tí ó ṣì fún ara rẹ̀ ni. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا) 10:108; 17:15; 39:41
- Ìdí ni wọn kò fi sọ àmì kan kalẹ̀ fún un láti ọ̀dọ̀ Olúwa rẹ̀? Sọ pé: "Dájúdájú..." (لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 13:27; 29:50
- Àwọn tí ó gbàgbọ́, tí wọn sì ń ṣe iṣẹ́ rere, wọn ní ẹ̀san tí kìí dáwọ́ dúró. (الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 41:8; 84:25; 95:6
- O sì ń mú ohun alààyè jáde láti inú ohun aláìlàyè, o sì ń mú ohun aláìlàyè jáde láti inú ohun alààyè. (وَتُخْرِجُ الْحَيَّ مِنَ الْمَيِّتِ وَتُخْرِجُ الْمَيِّتَ مِنَ الْحَيِّ) 3:27; 10:31; 30:19
- Ẹnikẹ́ni tí kò bá ṣe ìdájọ́ pẹ̀lú ohun tí Allah sọ̀kalẹ̀, àwọn wọ̀nyẹn ni... (وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللَّهُ فَأُولَئِكَ هُمُ) 5:44; 5:45; 5:47
- Ó dá àwọn ọ̀run, ilẹ̀, ati ohun tí ó wà láàrín wọn ní ọjọ́ mẹ́fà. (خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ) 25:59; 32:4; 50:38
- Dájúdájú, Allah ni Ẹlẹ́bùn fún àwọn ènìyàn, ṣùgbọ́n ọ̀pọ̀... (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ) 2:243; 10:60; 40:61
- Allah kò ṣe àleṣe sí wọn, ṣùgbọ́n àwọn ara wọn ni wọn ń ṣe àleṣe. (فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 29:40; 30:9
- Yóò dárí ẹ̀ṣẹ̀ yín jì, yóò sì fi yín sínú àwọn ọgbà Ọ̀run tí àwọn odò ń ṣàn ní abẹ́ wọn. (عَنكُمْ سَيِّئَاتِكُمْ وَلَأُدْخِلَنَّكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 5:12; 64:9; 66:8
- Ó ti ṣe e lèèwọ̀ fún yín ẹran ti ó ti kú, ẹ̀jẹ̀, ẹran ẹlẹ́dẹ̀, ati ohun tí a pa ní orúkọ yàtọ̀ sí Allah. (حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 5:3; 16:115
- Dájúdájú, èmi ń bẹ̀rù, bí mo bá ṣàìgbọràn sí Olúwa mi, ìyà Ọjọ́ ńlá. (إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 10:15; 39:13
- Àyàfi lẹ́yìn tí ìmọ̀ bá ti dé bá wọn, nítorí owú láàrín wọn. (إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ) 3:19; 42:14; 45:17
- Wọn sì fi ìrúnnú ṣe, wọn sì ń fúnni lọ́rẹ́ ohun tí A pèsè fún wọn, ni ìkọ̀kọ̀ àti ni gbangba. (وَأَقَامُوا الصَّلَاةَ وَأَنفَقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَةً) 13:22; 14:31; 35:29
- Yàtọ̀ sí Allah, ohun tí kò le ṣe wa láǹfààní bẹ́ẹ̀ ni kò le ṣe wa láleṣe. (مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106; 25:55
- Wọn ń gbàgbọ́ nínú ohun tí A sọ̀kalẹ̀ fún ọ, ati ohun tí A sọ̀kalẹ̀ ṣáájú rẹ. (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- Ṣe o kò rí i pé Allah sọ omi kalẹ̀ láti ọ̀run? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- Nígbà tí Ó bá pinnu ohun kan, Ó máa sọ fún un ni: "Ṣe!" yóò sì ṣe. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- Sí Madiyan, a rán arákùnrin wọn Shu'ayb. Ó sọ pé: "Ẹ̀yin ènìyàn mi! Ẹ sin Allah." (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- Iyen jẹ́ lára àwọn ìtàn ìkọ̀kọ̀ ti A fi ń ṣí i fún ọ. O kò sí bá wọn... (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- Nígbà tí àkúkọ̀ wọn bá dé, wọn kò lè fà á sẹ́yìn fun wákàtí kan, bẹ́ẹ̀ ni wọn kò lè mú u ṣíwájú. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- Ẹ má ṣe tẹ̀ lé àwọn ìgbésẹ̀ Eṣu, dájúdájú ó jẹ́ ọ̀tá gbangba fún yín. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- Láàrín àwọn ènìyàn, àwọn kan ń jiyàn nipa Allah láìsí ìmọ̀. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- Allah ń fúnni lọ́rẹ́ ohun tí Ó bá fẹ́, Allah sì ni Ọlọ́láńlá. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- Gbogbo ẹ̀mí yóò san ẹ̀san ohun tí ó ṣe ní kíkún, wọn kì yóò sì ṣe àleṣe sí wọn. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- Ẹ má ṣe pa ẹ̀mí tí Allah ti ṣe e lèèwọ̀, àyàfi nítorí ẹ̀tọ́. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- Nígbà tí Ó bá pinnu ohun kan, Ó máa sọ fún un ni: "Ṣe!" (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- Ẹ wọ̀ inú àwọn ibodè ọ̀run-àpáàdì, ẹ máa gbé inú rẹ̀ láéláé; ibùgbé àwọn agbéraga burú gidigidi! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- Ṣe o kò rí àwọn tí A fún ní apakan nínú Tìwà? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- Wọn ní àwọn ọgbà Ọ̀run tí àwọn odò ń ṣàn ní abẹ́ wọn, wọn yóò máa gbé inú rẹ̀ láéláé. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- Ẹ̀yin ènìyàn mi! Ẹ máa ṣiṣẹ́ lórí ipò yín, èmi ń ṣiṣẹ́, ẹ ó sì mò ní kíá. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- Ẹnikẹ́ni tí ó bá ṣàìgbọràn sí Allah ati Ojise Rẹ̀, ni iná ọ̀run-àpáàdì wà fún un, yóò máa gbé inú rẹ̀ láéláé. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- Ní ọkàn wọn ni ìbórí wà, ki wọn kì baà lóye rẹ̀, ati pé ní etí wọn ni wíwúwo wà. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- Kò sí ìlú kan tí a rán olùkilọ̀ sí, àyàfi àwọn ọlọ́rọ̀ rẹ̀ wí pé: "Àwa..." (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- Wọ́n ní: "Ẹ bẹ Olúwa rẹ fún wa kí ó sì ṣàlàyé fún wa ohun tí ó jẹ́." (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- Wọn yóò sọ: "Allah." Sọ pé: "Gbogbo ògo ní ti Allah!" Ṣùgbọ́n ọ̀pọ̀ wọn... (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- Ìdáhùn àwọn ènìyàn rẹ̀ kò jẹ́ nǹkan mìíràn, àyàfi wí pé: "Ẹ lé wọn jáde..." (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- Ní abẹ́ wọn ni àwọn odò ń ṣàn, wọn yóò máa gbé inú rẹ̀ láéláé. Iyẹn ni àṣeyọrí ńlá. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- Àwọn wọ̀nyẹn ni wọ́n wà lórí ìmọ̀nà láti ọ̀dọ̀ Olúwa wọn, àwọn wọ̀nyẹn sì ni àṣeyọrí. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- Ẹnikẹ́ni tí ìyà ìtìjú bá dé bá, tí ìyà gbígbẹ́ sì bá sọ̀kalẹ̀ sí i. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- Ẹ rìn kiri lórí ilẹ̀, ẹ sì wo bí òpin àwọn ẹlẹ́sìn-ẹ̀dà ṣe rí! (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- Wọn kì yóò fẹ́ rẹ̀ láéláé, nítorí ohun tí ọwọ́ wọn ti ní ilẹ̀ síwájú. Allah sì mọ àwọn alágbàṣe. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- Òun mọ ẹni tí ó ṣì kúrò lọ́nà Rẹ̀, Òun sì mọ... (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- Dájúdájú, Allah ni Olúwa mi ati Olúwa yín, nítorí náà ẹ sin Òun. Èyí ni ọ̀nà tó ń tọ̀. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- Ọlọ́láńlá fún àwọn ènìyàn, ṣùgbọ́n ọ̀pọ̀ wọn kò dúpẹ́. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Àwọn ọ̀run, ilẹ̀, ati ohun tí ó wà láàrín wọn, àyàfi pẹ̀lú òtítọ́ àti àkókò pàtó. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Fi wọ́n sílẹ̀ kí wọn kí ó máa ṣàdédé kí wọn kí ó sì máa ṣeré títí wọn yóò fi pàdé ọjọ́ wọn tí wọ́n ti ṣèlérí fún wọn. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- Nígbà tí wọn bá pàdé àwọn tí ó gbàgbọ́, wọ́n ní: "A gbàgbọ́," ṣùgbọ́n nígbà tí wọ́n bá wà nìkan... (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- Wọn fi Ìwé Mose àti Ìwé Injili múlẹ̀, àti ohun tí A sọ̀kalẹ̀ fún wọn láti ọ̀dọ̀ Olúwa wọn. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- Ó mọ ohun tí ó wà níwájú wọn, àti ohun tí ó wà lẹ́yìn wọn, wọn kì yóò sì yí i ká... (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- Òun ni Ẹni tí ó dá àwọn ọ̀run àti ilẹ̀ ní ọjọ́ mẹ́fà. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- Dájúdájú, nínú nkan yen ni àmì kan wà fún yín, bí ẹ bá jẹ́ onígbàgbọ́. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Kí ló sì dí àwọn ènìyàn lọ́wọ́ lati gbàgbọ́, nígbà tí ìmọ̀nà bá ti dé bá wọn? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- Wọ́n sọ àwọn alábàákẹ́gbẹ́ fún Allah, láti fi ta àwọn eniyan lọ́nà Rẹ̀. Sọ pé: "Ẹ gbádùn..." (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- Wọ́n yà nígbà tí olùkilọ̀ kan láti ara wọn dé bá wọn, àwọn aláìgbàgbọ́ sì ní: "Èyí..." (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Dájúdájú, Olúwa rẹ̀ mọ ẹni tí ó ṣì kúrò lọ́nà Rẹ̀. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Bí ẹni tí ń ná owó rẹ̀ fún híhàn fún àwọn ènìyàn, tí kò sì gbàgbọ́ nínú Allah. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Ẹ fi lára ohun tí A pèsè fún yín, kí nǹkan tí ó ... tó dé. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- Ó sọ ohun tí ó wà ní àwọn ọ̀run àti ohun tí ó wà lórí ilẹ̀ wà lábẹ́ àṣẹ yín. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- Dájúdájú, àwa wà ní ìyèméjì nipa ohun tí ẹ ń pè wá sí. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Dájúdájú, Olúwa rẹ̀ ń mú oúnjẹ pọ̀ sí i fún ẹni tí Ó bá fẹ́, Ó sì ń dín kù. Dájúdájú, Òun... (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Olúwa àwọn ọ̀run, ilẹ̀, ati ohun tí ó wà láàrín wọn, bí ẹ bá jẹ́ aláìdúbúlẹ̀. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- A gbàgbọ́ nínú Allah, àti ohun tí A sọ̀kalẹ̀ fún wa, àti ohun tí A sọ̀kalẹ̀ fún... (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- Àwọn alágbàṣe ni ariwo ńlá mú, wọn sì fi bẹ́ẹ̀ sílẹ̀ ní ìpọ́nlẹ́ nínú ilé wọn. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Kò sí ẹ̀ṣẹ̀ fún yín nínú ohun tí wọn bá ṣe nípa ara wọn. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Olúwa rẹ̀ mọ ẹni tí ó ṣì kúrò lọ́nà Rẹ̀, Òun sì... (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- Pẹ̀lú Ẹ̀mí (Àṣírí) láti inú àṣẹ Rẹ̀, sí ẹni tí Ó bá fẹ́ lára àwọn ẹrú Rẹ̀. (بِالُّرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- A sì fún Ọmọ Màríà, Isa, ní àwọn ẹ̀rí tó ṣe kedere, a sì fi Ẹ̀mí Mímọ́ fún un lókun. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- Láti fi dá ẹjọ́ láàrín wọn ni Ọjọ́ Àjínkí, nipa ohun tí wọn ń ṣe àríyànjiyàn. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- A sọ òkè rẹ̀ di ìsàlẹ̀, a sì rọ̀ òjò òkúta amọ̀ sí wọn. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Ó dọ́gba fún wọn, kí o bá a kìlọ̀ tàbí kí o má kìlọ̀, wọn kì yóò gbàgbọ́. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Yàtọ̀ sí àwọn ènìyàn, ẹ sì fẹ́ ikú bí ẹ bá jẹ́ aláòótọ́. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Ẹ sin Allah, ẹ kò ní ọlọ́run mìíràn yàtọ̀ sí Un. Ṣebí ẹ kò ni lẹ́rù? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Bí A bá fi díẹ̀ lára ohun tí A ṣèlérí fún wọn hàn ọ́, tàbí kí A kúkú mú ọ lọ, sí Ọ̀dọ̀ Wa ni wọn yóò padà... (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- Wọ́n ní: "Ṣebí tí a bá kú, tí a sì di erùpẹ̀ àti egungun, àwa ni a ó jí dìde?" (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Dájúdájú, Ọlọ́láńlá wà lọ́wọ́ Allah, Ó ń fi fún ẹni tí Ó bá fẹ́. Allah... (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- Sí Ẹni tí ó mọ ìkọ̀kọ̀ àti ìgbangba, Yóò sì sọ ohun tí ẹ̀ ń ṣe fún yín. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- Ẹ̀yin tí ẹ gbàgbọ́! Ẹ rántí oore-ọ̀fẹ́ Allah fún yín, nígbà tí... (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- A kò ránṣẹ́ ṣáájú rẹ àyàfi àwọn ọkùnrin tí A ń ṣí àṣírí fún. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- Yóò dárí ẹ̀ṣẹ̀ rẹ̀ jì, yóò sì fi í sínú àwọn ọgbà Ọ̀run tí àwọn odò ń ṣàn ní abẹ́ wọn. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- Tí ó bá jẹ́ aláìsàn tàbí tí ó wà lórí ìrìn-àjò, ṣe iye ọjọ́ mìíràn. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- Wọn kò tẹ̀ lé nǹkan bí kò ṣe ìrònú, wọn kì yóò sì ṣe nǹkan bí kò ṣe àdáwò. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Dájúdájú, àpẹẹrẹ rere wà fún ẹni tí ó ń retí Allah àti Ọjọ́ Ìkẹyìn. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- A kò dá àwọn ọ̀run, ilẹ̀, ati ohun tí ó wà láàrín wọn, àyàfi pẹ̀lú òtítọ́. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Fi ọwọ́ rẹ̀ sínú àpò rẹ̀, yóò jáde funfun, láìsí àbàwọ́n. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- Ó ń yan àǹfààní Rẹ̀ fún ẹni tí Ó bá fẹ́, Allah sì ni Ọlọ́láńlá. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- Ṣé o ò mọ̀ pé Allah ló ní ìjọba àwọn ọ̀run àti ilẹ̀? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- Ohun rere èyíkéyìí tí ẹ bá rán síwájú fún ara yín, ẹ ó rí i ní ọ̀dọ̀ Allah. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- Láti ibikíbi tí o bá ti jáde, yi ojú rẹ̀ síhà Mossalassi Mímọ́. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- Wọ́n ti kọjá lọ níṣáájú, iwọ kì yóò sì rí ìyípadà nínú ìlànà Allah. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- Ẹni tí ohun gbogbo tí ó wà ní àwọn ọ̀run àti ilẹ̀ jẹ́ tirẹ̀. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- Kò sí obìnrin kan tí ó lóyún tàbí tí ó bímọ, àyàfi pẹ̀lú ìmọ̀ Rẹ̀. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- Òru, Ó sì rọ àwọ̀n oòrùn àti òṣùpá wà lábẹ́ àṣẹ, ọ̀kọ̀ọ̀kan ń sáré fún àkókò pàtó. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Ní abẹ́ wọn ni àwọn odò ń ṣàn, wọn yóò máa gbé inú rẹ̀ láéláé, iyẹn sì ni ẹ̀san... (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- Ó ní: "Bẹ́ẹ̀ kọ́, ṣùgbọ́n ọkàn yín ti gbé nǹkan lọ́ṣọ̀ fún yín. Fún ìfaradà sì dára." (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- Ohun tí ó wà ní àwọn ọ̀run àti ohun tí ó wà lórí ilẹ̀, ati pé Allah... (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- Kò sí òjíṣẹ́ kan tí ó bá wọn wá, àyàfi wọn ń fi í ṣe ẹlẹ́yà. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- Wọ́n ní: "Ìwọ Musa, ìwọ yóò ju tàbí àwa ni a ó ju?" (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- Òun ni ń mú kí ẹ kú, láàrín yín ni ẹni tí a ó dá sílẹ̀ sí ọjọ́ ogbó, kí... (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- Wọn ní àwọn ọgbà Ọ̀run ní ọ̀dọ̀ Olúwa wọn, tí àwọn odò ń ṣàn ní abẹ́ wọn, wọn yóò máa gbé inú rẹ̀ láéláé. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- A sì fi ìbórí sí ọkàn wọn, kí wọn kì baà lóye rẹ̀, àti ní etí wọn... (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Dájúdájú, ìlérí Allah jẹ́ òtítọ́, ṣùgbọ́n ọ̀pọ̀ wọn kò mọ̀. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- Èyí nítorí wí pé wọn tako Allah ati Ojise Rẹ̀, ẹnikẹ́ni tí ó bá sì tako Allah... (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- Ní ọjọ́ tí Òun yóò pè wọn, tí yóò sì wí pé: "Níbo ni àwọn alábàákẹ́gbẹ́ Mi tí ẹ̀ ń sọ wà?" (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- Ṣebí wọn kò rí i pé Allah, Ẹni tí ó dá àwọn ọ̀run àti ilẹ̀...? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- Ẹni tí ó dá ọ́ láti inú erùpẹ̀, lẹ́yìn náà láti inú atọ́mí, lẹ́yìn náà... (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- Wọn yóò sọ pé: "Olúwa wa! Ìbáwù lọ́, ìwọ ì bá ránṣẹ́ sí wa, àwa ì bá tẹ̀ lé àwọn ẹ̀rí Rẹ!" (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Lẹ́yìn náà, sí ọ̀dọ̀ Olúwa wọn ni wọn yóò padà, Yóò sì sọ ohun tí wọn ń ṣe fún wọn. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- Wọn kò ní ìmọ̀ nípa rẹ̀, wọn kò tẹ̀ lé nǹkan bí kò ṣe... (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Dájúdájú, a rí àwọn baba wa lórí ẹ̀sìn kan, àwa sì ń tẹ̀ lé àwọn ìgbésẹ̀ wọn. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- Àwọn tí a fún ní Tìwà, àyàfi lẹ́yìn tí ìmọ̀ bá dé bá wọn... (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- Nígbà tí Ibrahima wí pé: "Olúwa mi! Ṣe ilú yìí di aláàlàáfíà." (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- Ó sì fún yín ní etí, ojú, àti ọkàn, ṣùgbọ́n díẹ̀ ni ẹ ń dúpẹ́. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- Àwọn tí ń jiyàn nipa àwọn ẹ̀rí Allah láìsí àṣẹ èyíkéyìí tí ó tó wọn. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Nítorí náà, ẹ tẹ̀ lé ẹ̀sìn Ibrahima, ẹni tí ó rìnrìn-àjò tó, kò sì sí lára àwọn alágbàṣe. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- Nígbà tí A gba yín là kúrò lọ́wọ́ àwọn ènìyàn Fír'awn, ti wọn ń fi ìyà tó burú jẹ yín. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- Ìyẹn ni ẹ̀sìn tó ń tọ̀, ṣùgbọ́n ọ̀pọ̀ ènìyàn kò mọ̀. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- Ṣe o kò rí i pé Allah rọ ohun gbogbo tí ó wà nínú... fún yín? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Àwọn aláìgbàgbọ́ wí pé: "Èyí kò jẹ́ nǹkan bí kò ṣe idán gbangba." (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- Nígbà tí wọ́n bá ń kà àwọn ẹ̀rí Wa tó ṣe kedere sí wọn, àwọn aláìgbàgbọ́ wí pé... (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Àwọn ọgbà Ọ̀run tí ó wà nǹkan tí àwọn odò ń ṣàn ní abẹ́ wọn, wọn yóò máa gbé inú rẹ̀ láéláé. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- Ohun tí Ó bá fẹ́, dájúdájú Allah ni Alágbára lórí gbogbo nǹkan. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- Láti dárí ẹ̀ṣẹ̀ yín jì, àti láti fa àkókò yín síwájú sí àkókò pàtó. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Ẹ̀ ń fẹ́ lé wa kúrò nínú ohun tí àwọn baba wa ń sin. (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- Nígbà tí Olúwa rẹ̀ sọ fún àwọn Mọlaika pé: "Èmi ń dá ẹ̀dá ènìyàn láti inú..." (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- Òun sì ni Ẹni tí ń rán àwọn ẹ̀fúùfù gẹ́gẹ́ bí ìhìn rere níwájú àánú Rẹ̀. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Sọ pé: "Ẹ rìn kiri lórí ilẹ̀ kí ẹ sì wo bí òpin ... ṣe rí." (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- Dájúdájú, nínú ìṣẹ̀dá àwọn ọ̀run àti ilẹ̀, àti ìyípadà òru àti ọ̀sán (ni àwọn àmì wà). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Ta ni ẹni tí yóò fi Ọlọ́ránńlá àwín fún Allah, tí Òun yóò sì ṣe é pọ̀ sí i fún un? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Nítorí náà, ẹ ṣe ìdájọ́ láàrín wọn pẹ̀lú ohun tí Allah sọ̀kalẹ̀, ẹ má sì tẹ̀ lé ìfẹ́ ọkàn wọn. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- Ṣebí wọn ń retí nǹkan mìíràn bí kò ṣe pé àwọn Mọlaika kí ó tọ́ wọn wá, tàbí kí Olúwa rẹ̀ wá...? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Dájúdájú, àwọn tí ń pèdà irọ́ sórí Allah, kì yóò ṣàṣeyọrí. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- Gẹ́gẹ́ bí àṣà àwọn ènìyàn Fír'awn àti àwọn tí ó ṣáájú wọn, wọ́n sọ àwọn ẹ̀rí Wa di irọ́. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- Kí o sì máa fún àwọn onígbàgbọ́ tí ń ṣe iṣẹ́ rere ní ìhìn rere, pé wọn ní ẹ̀san ńlá... (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Allah ń mú oúnjẹ pọ̀ sí i fún ẹni tí Ó bá fẹ́ lára àwọn ẹrú Rẹ̀, Ó sì ń dín kù. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- Ẹ ó sì padà sí Ọ̀dọ̀ Ẹni tí ó mọ ìkọ̀kọ̀ àti ìgbangba, Yóò sì sọ ohun tí ẹ̀ ń ṣe fún yín. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- Àwọn ìbátan jẹ́ aláṣẹ jù fún ara wọn nínú Tìwà Allah. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — dandan (a gbọdọ ṣe; ẹ̀ṣẹ̀ ni láti yọ̀ǹda)
- mustahabb / mandub (مستحب / مندوب) — tí a ṣe ìyànjú (ẹ̀san fún ṣíṣe, kì í ṣe ẹ̀ṣẹ̀ láti yọ̀ǹda)
- mubah (مباح) — ààrín / tí a gbà (kò sí ẹ̀san tàbí ẹ̀ṣẹ̀)
- makruh (مكروه) — tí a kò fẹ́ràn (a kò gbani níyànjú, ṣùgbọ́n kì í ṣe ẹ̀ṣẹ̀ láti ṣe)
- haram (حرام) — èèwọ̀ (ẹ̀ṣẹ̀ ni láti ṣe)
- halal (حلال, tí a gbà / tí ó bófin mu) — ó ní nkan ti mubah àti mustahabb — ohunkóhun tí a kò fòfindè
- Ẹ jọ́sìn Allah nìkan kí ẹ sì máa wá ìrànwọ́ lọ́dọ̀ Rẹ̀. 1:5
- Ẹ jọ́sìn Allah nìkan 2:21
- Ẹ má ṣe fi ohun kankan ṣe alábàápín fún Allah 2:22
- Allah ni Ẹni tí ó ń dáríjì (tí ń gba ìrònúpìwàdà), Ó gba ìrònúpìwàdà Ádámù (عَلَيْهِ ٱلسَّلَامُ). 2:37
- Ẹ má ṣe dapọ̀ òtítọ́ pẹ̀lú èké, bẹ́ẹ̀ ni ẹ má ṣe fi òtítọ́ pamọ́. 2:42
- Ẹ máa ṣe àdúrà (àwọn àdúrà ojoojúmọ́), kí ẹ sì máa fúnni ní Zakat (ọrẹ́). 2:43
- Ẹ pa a láṣẹ fún àwọn ẹlòmíràn nípa ìwà rere lẹ́yìn tí ẹ̀yin fúnra yín bá ti ń ṣe é 2:44
- Ẹ máa wá ìrànwọ́ Allah nínú gbogbo àwọn ọ̀ràn yín 2:45
- Ẹ má ṣe lọ́wọ́ nínú tàbí kí ẹ máa tànkálẹ̀ ìbàjẹ́ 2:60
- Ẹ má ṣe dá àwọn ènìyàn lẹ́kun láti lọ sí àwọn ibi ìjọsìn 2:114
- Ẹ máa bọ̀wọ̀ fún mímọ́ ilé mọ́sálásí. Ẹ máa pa àwọn ibi àdúrà yín mọ́ pátápátá 2:125
- Ẹ máa rántí Allah (nípa àdúrà, yin, àti bẹ́ẹ̀ bẹ́ẹ̀ lọ) Ẹyin náà yóò rántí yín, kí ẹ sì máa dúpẹ́ lọ́wọ́ Rẹ̀. 2:152
- Ẹ máa fi sùúrù nínú ìpọ́njú 2:153
- Ẹ má ṣe tẹ̀lé àwọn ipasẹ̀ Ẹ̀ṣù (Sátánì) tí í ṣe ọ̀tá gbangba. 2:168
- Ẹ má ṣe tẹ̀lé ẹnikẹ́ni lójú afọ́jú 2:170
- Ẹ máa pa gbogbo àwọn ohun tí a fi sílẹ̀ mọ́ kí ẹ sì ṣe wọn. Ẹ máa ṣe àwọn ojúṣe ẹ̀sìn yín pẹ̀lú òótọ́. Ẹ máa pa àwọn ìbúra àti àwọn májẹ̀mú yín mọ́. Ẹ máa pa àwọn ìlérí yín mọ́, ní pàtàkì àwọn tí a ṣe fún Allah. Ẹ máa ṣe àtìlẹ́yìn fún àwọn aláìní kí ẹ sì máa dín ìnira kù. Ẹ máa yàgò fún ṣíṣe àwọn ẹ̀ṣẹ̀ tí ń mú kí ènìyàn pàdánù ojú rere Ọlọ́run. Ẹ má ṣe jẹ́ kí ìgbéraga gbé yín lọ síwájú nínú àìṣe òdodo 2:177
- (Ìgbàlà) wà fún yín nínú Qisas (Òfin ìdógba nínú ìjìyà). 2:179
- Ẹ máa gbààwẹ̀ ní oṣù Ramadan. Ẹ máa pa àwẹ̀ tí a pa láṣẹ mọ́ kí ẹ̀yin kí ó lè di àwọn Al-Muttaqun (àwọn Ọlọ́runfẹ́). 2:183
- Ẹ máa bọ̀wọ̀ fún Al-Ƙur’ān gẹ́gẹ́ bí orísun ìmọ̀ tí ó ga jùlọ 2:185
- Ẹ má ṣe jẹ ohun ìní ara yín lọ́nà àìṣe òdodo, bẹ́ẹ̀ ni ẹ má ṣe fún àwọn adájọ́ ní ẹ̀bùn (kí ẹ tó ṣe àwọn ẹjọ́ yín síwájú wọn). 2:188
- Ẹ má ṣe fi àwọn ẹlòmíràn ni ipá, yálà nípa ọ̀rọ̀ tàbí nípa ìṣe. Ẹ má ṣe jagun rí gẹ́gẹ́ bí alágbèrè, bí kò ṣe fún ààbò nìkan 2:190
- Ẹ máa dáàbò bo àwọn ọmọ ọ̀tá. Ní ti àwọn ọmọ ọ̀tá, ẹ máa fi òótọ́ ṣiṣẹ́ nínú ohun ìní wọn kí ẹ má sì jẹ ohun ìní wọn. 2:220
- Ẹ máa ronúpìwàdà kí ẹ sì máa bẹ̀bẹ̀ fún ìdáríjì lọ́dọ̀ Allah. Ẹ má ṣe ní ìbálòpọ̀ ní àsìkò oṣù. Ẹ máa pa mímọ́ (ní ti ara àti ní ti ẹ̀mí) mọ́ 2:222
- Ẹ máa ṣe ojúṣe yín sí ẹbí yín 2:233
- Ẹ máa yan àwọn aṣáájú lórí ipò wọn 2:247
- Ẹ má ṣe fi ipá mú ènìyàn nínú ẹ̀sìn 2:256
- Ẹ máa ná ohun ìní yín nínú iṣẹ́ ọ̀rẹ́. Ẹ máa jẹ́ aláàánú nípa ohun ìní àti àkókò 2:261
- Ẹ má ṣe sọ iṣẹ́ ọ̀rẹ́ di asán nípa fífi àánú yín ṣe ìgbéraga 2:264
- Ẹ̀ṣù (Sátánì) ń halẹ̀ mọ́ yín pẹ̀lú òṣì, ó sì ń pa yín láṣẹ láti ṣe iṣẹ́ ẹ̀gbin (àwọn ẹ̀ṣẹ̀). 2:268
- Ẹ máa wá àwọn aláìní kí ẹ sì máa ran wọn lọ́wọ́ 2:273
- Ẹ má ṣe lọ́wọ́ nínú èlé. Ẹ má ṣe jẹ ohun ìní tí ó ní èlé. Ẹ má ṣe jẹ Riba (èlé). 2:275
- Ẹ fi àkókò sílẹ̀ fún onígbèsè tí ó bá wà nínú ìṣòro 2:280
- Ẹ máa pa ọ̀rọ̀ yín mọ́ nínú àwọn òwò. Ẹ máa jẹ́ olóòótọ́ nínú àwọn ọ̀ràn owó yín. Ẹ máa ṣe pẹ̀lú òótọ́ nínú gbogbo àwọn ìlérí yín. Nígbà tí ẹ bá ṣe adehun gbèsè fún àkókò pípẹ́, ẹ kọ ọ́ sílẹ̀. Ẹ máa mú ẹlẹ́rìí ní gbogbo ìgbà tí ẹ bá ń ṣe adehun òwò. 2:282
- Ẹ máa pa gbogbo àwọn ohun tí a fi sílẹ̀ mọ́ kí ẹ sì ṣe wọn 2:283
- Ẹ máa gba àwọn Ìwé Mímọ́ tí a fi ránṣẹ́ àti gbogbo àwọn Ànábì gbọ́ 2:285
- Ọlọ́run kì í fi ẹrù tí ó kọjá agbára ẹ̀yà ara ẹ̀dá. Wọn ó gba ẹ̀san fún ohun (tí ó dára) tí wọ́n ṣiṣẹ́, wọn yóò sì jẹ́ ìjìyà fún ohun (tí ó burú) tí wọ́n ṣiṣẹ́. Ọlọ́run kì í fi ẹrù tí ó kọjá agbára ẹ̀yà ara ẹ̀dá; bẹ́ẹ̀ ni àwa kò sì gbọ́dọ̀ ṣe bẹ́ẹ̀. Ẹ máa gbọ́kànlé ètò Allah láàárín ìpọ́njú 2:286
- Ẹnikẹ́ni tí ó bá pa àwọn májẹ̀mú mọ́ tí ó sì ń bẹ̀rù Allah, nígbà náà Allah nífẹ̀ẹ́ àwọn Ọlọ́runfẹ́. 3:76
- Ẹ máa ṣe Hajj (ìrìn àjò mímọ́) bí ẹ bá lè ṣe é 3:97
- Ẹ má ṣe yapa 3:103
- Ẹ máa pa àṣẹ fún ohun tí ó tọ́ kí ẹ sì máa kọ̀ ohun tí ó burú. Ẹ máa fúnni níṣìírí fún òdodo nínú àwùjọ yín. Ẹ máa pe àwọn ẹlòmíràn sí ìrántí Allah 3:104
- Lórí Allah ni àwọn onígbàgbọ́ gbọ́dọ̀ gbára lé. 3:122
- Ẹ má ṣe jẹ Riba (èlé). 3:130
- Ẹ máa ṣe ìgbọràn sí Allah àti Ojúṣe Rẹ̀ kí ẹ lè rí àánú. 3:132
- Allah nífẹ̀ẹ́ àwọn tí ń ná (ní Ọ̀nà Allah – iṣẹ́ ọ̀rẹ́, àjẹ́, àti bẹ́ẹ̀ bẹ́ẹ̀ lọ) ní àkókò àásìkí àti àkókò ìpọ́njú, tí ń fa ìbínú sẹ́yìn, tí ń sì dáríjì fún àwọn ènìyàn. 3:134
- Ẹ máa fa ìbínú sẹ́yìn. 3:134
- Ẹ máa dáríjì fún àwọn àṣìṣe ẹlòmíràn 3:135
- Ẹ má ṣe jẹ́ aláìnítìjú nínú ọ̀rọ̀. Ẹ máa fi sùúrù pẹ̀lú àwọn tí ó yàtọ̀ sí yín 3:159
- Bí Allah bá ràn yín lọ́wọ́, kò sí ẹni tí lè ṣẹ́gun yín; bí ó bá sì kọ̀ yín sílẹ̀, ta ni lẹ́yìn Rẹ̀ tí yóò ràn yín lọ́wọ́? 3:160
- Gbogbo ẹ̀dá yóò dánu ikú. Kì yóò sì jẹ́ bí kò ṣe ní Ọjọ́ Àjíǹde ni ẹ ó gba ẹ̀san yín ní kíkún. 3:185
- Ẹ máa ronú jínjìn nípa àwọn ìyanu ẹ̀dá àti ìṣẹ̀dá àgbáyé yìí. Ẹ mọ̀ pé Ọlọ́run dá àgbáyé pẹ̀lú ìtumọ̀ àti ète 3:191
- Ọkùnrin àti obìnrin ní ẹ̀san kanna fún àwọn iṣẹ́ wọn 3:195
- Fún àwọn tí ó bẹ̀rù Olúwa wọn, ni àwọn Ọgbà tí àwọn odò ń sàn ní abẹ́ wọn (nínú Ọ̀run); wọn ó máa gbé ibẹ̀ láé, gẹ́gẹ́ bí oúnjẹ láti ọ̀dọ̀ Allah. 3:198
- Ẹ máa sapá fún ìtẹ́lọ́rùn Allah nínú gbogbo ìṣe. 3:200
- Ẹ máa jẹ́ olóòótọ́ sí Olúwa yín, ẹ máa bẹ̀rù Rẹ̀ kí ẹ má sì (gé àwọn ìdè) ti ìbátan. 4:1
- Ẹ máa fún àwọn ọmọ ọ̀tá ní ohun ìní wọn, ẹ má sì fi (ohun) búburú yín pààrọ̀ pẹ̀lú (ohun) dídára wọn; ẹ má sì jẹ ohun ìní wọn (nípa fífi kún) ohun ìní yín. 4:2
- Ẹ máa fún àwọn obìnrin (tí ẹ ń ṣègbéyàwó) ní Mahr wọn (ọrẹ́ ìgbéyàwó tí ó jẹ́ dandan tí ọkọ yóò fún aya nígbà ìgbéyàwó) pẹ̀lú ọkàn tí ó dára. 4:4
- Ẹ máa da àwọn ẹ̀tọ́ àwọn ọmọ ọ̀tá ààbò 4:6
- Ohun ìní ẹni tí ó kú gbọ́dọ̀ pín fún àwọn ọmọ ẹbí rẹ̀. Àwọn obìnrin ní ẹ̀tọ́ ogún 4:7
- Ẹ má ṣe jẹ ohun ìní àwọn ọmọ ọ̀tá lọ́nà àìṣòdodo 4:10
- Ẹ máa tẹ̀lé àwọn àṣẹ nípa ogún 4:11
- A ti kọ̀ láti jogún àwọn obìnrin lọ́nà tí kò bá ìfẹ́ wọn mu, kí ẹ má sì ṣe fi ìkà bá wọn lò. Ẹ máa gbé pẹ̀lú wọn (àwọn aya) pẹ̀lú ọlá. Ẹ máa bọ̀wọ̀ kí ẹ sì máa pa àwọn ẹ̀tọ́ obìnrin mọ́. Ẹ máa fi ọ̀wọ̀ àti ìdájọ́ òdodo bá ọkọ tàbí aya yín lò. Ẹ máa fi ọ̀wọ̀ àti ìdájọ́ òdodo bá àwọn obìnrin lò 4:19
- Ẹ má ṣe fẹ́ àwọn tí ẹ̀jẹ̀ ẹ ní pẹ̀lú wọn 4:23
- Ẹ má ṣe pa ara yín (tàbí kí ẹ pa ara yín). Dájúdájú, Allah Ọlọ́run Àánú ni sí yín. Ẹ má ṣe jẹ ohun ìní ara yín lọ́nà àìṣòdodo 4:29
- Bí ẹ bá yàgò fún àwọn ẹ̀ṣẹ̀ ńlá tí a kà wọ́n lèèwọ̀, Allah yóò pa àwọn ẹ̀ṣẹ̀ yín (kékèké) mọ́, yóò sì mú yín wọ Ọ̀nà Ọlọ́lá (ìyẹn Ọ̀run). 4:31
- Ẹ má ṣe fẹ́ ohun tí Allah fi ṣe àkànṣe fún àwọn kan nínú yín ju àwọn ẹlòmíràn lọ. Ẹ máa yàgò fún ẹ̀tán àti ojúṣe 4:32
- Àwọn ọkùnrin ni àwọn alábojútó àti alábòójútó àwọn obìnrin, nítorí pé Allah ti fún àwọn kan ní àkànṣe ju àwọn ẹlòmíràn lọ, àti nítorí pé wọ́n ń ná láti inú ohun ìní wọn (láti bójútó wọn). Ọkùnrin ni alábojútó àti alátìlẹ́yìn ẹbí 4:34
- Ẹ máa jọ́sìn Allah, ẹ má sì máa ṣe alábàápín fún un, ẹ máa ṣe rere sí àwọn òbí, àwọn ìbátan, àwọn ọmọ ọ̀tá, àwọn òtòṣì, aládùúgbò, alábàákẹ́gbẹ́ tí ń bẹ lẹ́gbẹ̀ẹ́ yín, arìnrìn-àjò (tí ẹ bá pàdé), àti àwọn tí ọwọ́ ọ̀tún yín ń mú (àwọn ẹrú). Allah kì í fẹ́ àwọn onígbéraga àti ológo. Ẹ máa ṣe rere sí àwọn ẹlòmíràn. Ẹ máa ṣe àánú fún àwọn aláìlára. Ẹ máa pa ìdè ìbátan mọ́ kí ẹ sì máa bọ̀wọ̀ fún àwọn ìbátan. 4:36
- Ẹ má ṣe jẹ́ oníwọ́ra 4:37
- Allah kì í dáríjì pé kí a ṣe alábàápín fún un, ṣùgbọ́n Ó ń dáríjì ohun mìíràn yàtọ̀ sí i fún ẹni tí Ó bá fẹ́. 4:48
- Ẹ má ṣe máa ṣe ẹ̀tán sí àwọn ẹlòmíràn 4:54
- Allah ń pa yín láṣẹ pé kí ẹ máa fi ohun tí a fi sílẹ̀ fún yín padà sí àwọn oníwọn. Nígbà tí ẹ bá ń ṣe ìdájọ́ láàrín àwọn ènìyàn, ẹ máa fi òdodo ṣe ìdájọ́. 4:58
- Ẹ máa ṣe ìgbọràn sí Allah àti Ojúṣe Rẹ̀. Ẹ máa fi ọ̀wọ̀ tí ó yẹ fún àwọn tí ó ní ọlá àṣẹ láàrín yín 4:59
- Ẹ má ṣe fi àwọn aláìlágbára àti aláìlera ní ipá 4:75
- Ohunkóhun tí ó dára tí ó bá dé bá yín, ó ti ọ̀dọ̀ Allah wá, ṣùgbọ́n ohunkóhun tí ó burú tí ó bá dé bá yín, ó ti ọ̀dọ̀ ara yín wá. 4:79
- Ẹni tí ó bá tẹríba fún Ojúṣe (Muhammad ﷺ), ti tẹríba fún Allah. 4:80
- Ẹnikẹ́ni tí bá ṣe ìlàjù fún ohun rere, yóò rí èso rẹ̀, ẹnikẹ́ni tí ó bá sì ṣe ìlàjù fún ohun búburú, yóò ní apá kan nínú ẹrù rẹ̀. 4:85
- Kò tọ́ fún onígbàgbọ́ láti pa onígbàgbọ́ mìíràn, àyàfi nípa àìnímọ̀ọ́mọ̀. 4:92
- Ẹnikẹ́ni tí ó bá pa onígbàgbọ́ mọ̀ọ́mọ̀, èrè rẹ̀ ni ọ̀run àpáàdì, yóò sì máa gbé ibẹ̀ láé. Ìbínú àti ègún Allah wà lórí rẹ̀, a sì ti pèsè ìyà ńlá fún un. 4:93
- Ẹnikẹ́ni tí ó bá ṣe ìṣíkiri (lati ilé rẹ̀) ní ọ̀nà Allah, yóò rí ọ̀pọ̀lọpọ̀ ibi ìgbé àti ọ̀pọ̀lọpọ̀ oúnjẹ lórí ilẹ̀. 4:100
- Ẹ máa pa àkókò àwọn àdúrà yín mọ́ 4:103
- Ẹ má ṣe ṣe àtìlẹ́yìn fún tàbí kí ẹ jẹ́ agbẹjọ́rò fún àwọn tí ń da àwọn ohun tí a fi sílẹ̀ fún wọn pààrọ̀ 4:105
- Ẹ máa bẹ̀bẹ̀ fún ìdáríjì lọ́dọ̀ Allah; dájúdájú, Allah ń dáríjì, Ọlọ́run Àánú. 4:106
- Ẹ̀yin tí ẹ gbàgbọ́! Ẹ máa dúró ṣinṣin fún òdodo, gẹ́gẹ́ bí ẹlẹ́rìí fún Allah, bí ó tilẹ̀ jẹ́ pé ó lòdì sí ara yín, tàbí àwọn òbí yín, tàbí àwọn ìbátan yín, yálà ó jẹ́ ọlọ́rò tàbí òtòṣì. Ẹ má ṣe dá òdodo dúró; ẹ máa ṣe pẹ̀lú ìyára láti ṣàtúnṣe àwọn àìṣe òdodo 4:135
- Àwọn agàbàgebè ń gbìyànjú láti tan Allah jẹ, ṣùgbọ́n Òun ni Ó ń tan wọn jẹ. 4:142
- Àwọn agàbàgebè yóò wà ní ìsàlẹ̀ jùlọ Iná; kò sì ní sí olùrànlọ́wọ́ fún wọn. 4:145
- Allah kì í fẹ́ kí a sọ ohun búburú sókè ní gbangba, àyàfi láti ọ̀dọ̀ ẹni tí a ṣe àìṣòdodo sí. 4:148
- Àwọn Ojúṣe gẹ́gẹ́ bí olùgbéròyìn rere àti olùkìlọ̀, kí àwọn ènìyàn má bá a ní ìdáláre sí lọ́dọ̀ Allah lẹ́yìn (wíwá) àwọn Ojúṣe. 4:165
- Ẹ máa pa àwọn májẹ̀mú àti àwọn ìlérí yín mọ́ 5:1
- Ẹ máa ṣe ìrànwọ́ ara yín nínú iṣẹ́ rere àti ẹ̀rù Ọlọ́run, kí ẹ má sì ṣe ìrànwọ́ ara yín nínú ẹ̀ṣẹ̀ àti ìjà 5:2
- Ẹ má ṣe jẹ ẹran tí ó ti kú, ẹ̀jẹ̀, tàbí ẹran ẹlẹ́dẹ̀ 5:3
- Ẹ máa ṣe òdodo; ẹ má ṣe jẹ́ kí ọ̀tá àti ìkórìíra àwọn ẹlòmíràn mú yín yàgò fún òdodo. Ẹ máa jẹ́ olóòdodo ní àwọn ọ̀ràn yín. Ẹ mọ̀ pé òdodo sún mọ́ ẹ̀rù Ọlọ́run. Ẹ má ṣe dá òdodo dúró; ẹ máa ṣe pẹ̀lú ìyára láti ṣàtúnṣe àwọn àìṣe òdodo 5:8
- Ẹ máa wá àwọn ọ̀nà sí Allah, kí ẹ sì máa sapá nínú Ọ̀nà Rẹ̀ bí ó bá ṣeé ṣe fún yín, kí ẹ lè ṣàṣeyọrí. 5:35
- Ẹ máa pa àwọn ìbúra àti àwọn májẹ̀mú yín mọ́ 5:89
- Ẹ máa yàgò fún ohun mímu tí ń mu ọti àti ọtí. Ẹ máa yàgò fún ohun mímu tí ń mu ọti (gbogbo irú ohun mímu tí ó ní ọtí), ìṣeré ayò, òkúta, àti ọfà ìṣeré ayò, tí gbogbo rẹ̀ jẹ́ ẹ̀gbin iṣẹ́ Ẹ̀ṣù. 5:90
- Ẹ má ṣe pa ẹranko ìgbẹ́ nígbà tí ẹ bá wà nínú ìhram fún Hajj tàbí 'Umrah. 5:95
- Ẹ má ṣe béèrè nípa àwọn ohun tí, bí a bá ṣàlàyé wọn fún yín, lè mú wàhálà bá yín. 5:101
- Ẹ má ṣe bú àwọn òrìṣà àwọn ẹlòmíràn. Ẹ má ṣe bú àwọn tí wọ́n ń jọ́sìn (àwọn aláìgbàgbọ́) yàtọ̀ sí Allah, kí wọn má bá à bú Allah láìní ìmọ̀. 6:108
- Bí ẹ bá ń tẹ̀lé ọ̀pọ̀ àwọn tí ń bẹ lórí ilẹ̀, wọn yóò mú yín ṣínà kúrò ní Ọ̀nà Allah. Wọn kò tẹ̀lé ohunkóhun bí kò ṣe ìrò, wọn kò sì ṣe ohunkóhun bí kò ṣe irọ́. 6:116
- Ẹ fi gbogbo irú ẹ̀ṣẹ̀, tí ó hàn tàbí tí ó farasin, sílẹ̀ (ẹ̀yin ènìyàn!). 6:120
- Ẹ má ṣe jẹ (ẹ̀yin onígbàgbọ́!) láti ara ẹran tí a kò dárúkọ Allah lé lórí (nígbà tí wọ́n ń pa á). 6:121
- Ẹni tí Allah bá fẹ́ fi ọ̀nà hàn, Ó ń ṣí àyà rẹ̀ fún Islam, ẹni tí Ó bá sì fẹ́ fi ṣínà, Ó ń sọ àyà rẹ̀ di dín kù tí ó sì ń di dín mọ́. 6:125
- Ẹ máa jẹ́ alágbàtọ́ nínú ìnáwó, kí ẹ sì máa yàgò fún ìnáwó pípa jù. Ẹ máa pa àwọn ẹ̀tọ́ gbogbo ohun tí a dá mọ́ 6:141
- Ẹ má ṣe fi ohunkóhun ṣe alábàápín fún Allah nínú ìjọsìn, ẹ máa ṣe rere sí àwọn òbí, ẹ má ṣe pa àwọn ọmọ yín nítorí ìbẹ̀rù òṣì, ẹ má ṣe sún mọ́ àwọn ohun àbùkù, ẹ má ṣe pa ẹnikẹ́ni tí Allah kò gbà láyè, àyàfi pẹ̀lú ẹ̀tọ́. 6:151
- Ẹ máa jẹ́ olóòótọ́; ẹ má ṣe tan àwọn ẹlòmíràn jẹ nínú àwọn òwò yín. Ẹ má ṣe sún mọ́ ohun ìní ọmọ ọ̀tá, àyàfi láti mú un dára, ẹ máa fún ní kíkún odiwọn àti wíwọ̀n pẹ̀lú òdodo, nígbà tí ẹ bá ń sọ̀rọ̀, ẹ máa sọ òtítọ́, bí ó tilẹ̀ jẹ́ pé ó jẹ́ ìbátan tí ó sún mọ́ ara, kí ẹ sì máa pa májẹ̀mú Allah mọ́. 6:152
- Ẹ máa tẹ̀lé Ọ̀nà Tààrà, ẹ má sì máa tẹ̀lé àwọn ọ̀nà mìíràn, nítorí wọn yóò yín ya kúrò ní Ọ̀nà Rẹ̀. 6:153
- Ẹ sọ (Muhammad ﷺ): "Dájúdájú, àdúrà mi, ẹbọ mi, ìgbé ayé mi àti ikú mi jẹ́ ti Allah, Olúwa gbogbo ẹ̀dá." 6:162
- Ẹ má ṣe jẹ́ onígbéraga 7:13
- Ẹ má ṣe jẹ́ kí Ẹ̀ṣù (Sátánì) tan yín jẹ. 7:27
- Ẹ sọ (Muhammad ﷺ): "Olúwa mi pa òdodo láṣẹ..." 7:29
- Ẹ máa pa àwọn ààlà tí Allah gbé kalẹ̀ nínú gbogbo ọ̀ràn mọ́. Ẹ máa yàgò fún ìrékọjá nínú ọ̀rọ̀ àti ìṣe. Ẹ máa jẹ kí ẹ sì máa mu, ṣùgbọ́n ẹ má ṣe jẹ́ aláṣejù. Ẹ máa wọ aṣọ tí ó dára ní àkókò àdúrà 7:31
- Allah dá àwọn ọ̀run àti ilẹ̀ ní Ọjọ́ mẹ́fà, lẹ́yìn náà Ó fi ara rẹ̀ kalẹ̀ lórí Ibi-Ọba (ní ọ̀nà tí ó yẹ fún Ọ̀lá Rẹ̀). 7:54
- Ẹ máa képè Olúwa yín pẹ̀lú ìrẹ̀lẹ̀ àti ní ìkọ̀kọ̀. Kò fẹ́ àwọn aláṣejù. 7:55
- Ẹ má ṣe ṣe ìbàjẹ́ lórí ilẹ̀, lẹ́yìn tí a ti ṣe àtúntò rẹ̀, kí ẹ sì máa képè Rẹ̀ pẹ̀lú ìbẹ̀rù àti ìrètí. 7:56
- Ṣùgbọ́n àwọn tí wọ́n ṣe àwọn iṣẹ́ búburú, tí wọ́n sì ronúpìwàdà lẹ́yìn náà tí wọ́n sì gbàgbọ́, dájúdájú, Olúwa yín lẹ́yìn gbogbo náà ni Ọlọ́run Àánú, Ọlọ́run Aláàánú. 7:153
- Ẹ sọ (Muhammad ﷺ): "Ẹ̀yin ènìyàn! Dájúdájú, èmi ni Ojúṣe Allah sí gbogbo yín..." 7:158
- Gbogbo orúkọ rírẹwà jẹ́ ti Allah, nítorí náà ẹ máa képè Rẹ̀ pẹ̀lú wọn, kí ẹ sì máa fi àwọn tí ń yí orúkọ Rẹ̀ padà tàbí tí ń kọ̀ wọ́n sílẹ̀... 7:180
- Ẹni tí Allah bá fi ṣínà, kò sí aṣáájú fún un; Ó sì ń jẹ́ kí wọn máa rìn kiri nínú ìrékọjá wọn lójú afọ́jú. 7:186
- Ẹ máa fi ìdáríjì hàn, ẹ máa pa àṣẹ fún ohun tí ó dára, kí ẹ sì máa yípadà kúrò lọ́dọ̀ àwọn òmùgọ̀ (ìyẹn ẹ má ṣe jẹ wọn níyà). 7:199
- Ẹ máa dáríjì fún àwọn ẹlòmíràn nínú àwọn àṣìṣe wọn 7:199
- Bí ẹ̀rùn bá bá ẹ láti ọ̀dọ̀ Ẹ̀ṣù (Sátánì), ẹ máa wá ibi ààbò lọ́dọ̀ Allah. Dájúdájú, Òun ni Olùgbọ́, Olùmọ̀. 7:200
- Àwọn onígbàgbọ́ jẹ́ àwọn tí, nígbà tí a bá mẹ́nu bà Allah, ọkàn wọn yóò gbọ̀n, tí a bá sì ń ka àwọn Ẹsẹ Rẹ̀ wọn fún wọn, wọn yóò fi ìgbàgbọ́ pọ̀ sí i... 8:2
- Ẹ má ṣe da Allah àti Ojúṣe Rẹ̀ lẹ́bi, kí ẹ má sì mọ̀ọ́mọ̀ da àwọn ohun tí a fi sílẹ̀ fún yín (àwọn ohun tí a fi lé yín lọ́wọ́ àti gbogbo àwọn ojúṣe tí Allah pa láṣẹ fún yín) lẹ́bi. 8:27
- Bí ẹ bá tẹríba fún Allah kí ẹ sì bẹ̀rù Rẹ̀, Yóò fún yín ni Furqan (agbára láti mọ ìyàtọ̀ láàrín rere àti búburú). 8:29
- Àwọn aláìgbàgbọ́ ń ná ohun ìní wọn láti dènà (àwọn ènìyàn) kúrò ní Ọ̀nà Allah, wọn yóò sì máa ná an, ṹ̀gbọ́n nígbẹ̀yìngbẹ́yín yóò di ọ̀fọ̀ fún wọn. 8:36
- Ẹ sọ fún àwọn aláìgbàgbọ́, bí wọ́n bá dáwọ́ dúró (nínú àìgbàgbọ́), ohun tí ó ti kọjá yóò yí wọ́n dáríjì. ṹ̀gbọ́n bí wọ́n bá (sí i) padà, nígbà náà àwọn àpẹẹrẹ ti àwọn tí ó ṣáájú wọn ti kọjá (gẹ́gẹ́ bí ìkìlọ̀). 8:38
- Nígbà tí ẹ bá pàdé (agbára ọ̀tá), ẹ máa dúró ṣinṣin níwájú wọn, kí ẹ sì máa rántí orúkọ Allah púpọ̀ (pẹ̀lú ahọ́n àti pẹ̀lú ọkàn), kí ẹ lè ṣàṣeyọrí. 8:45
- Ẹ má ṣe dàbí àwọn tí ó jáde kúrò nílé wọn pẹ̀lú ìgbéraga àti fífi ara hàn fún àwọn ènìyàn, tí wọn sì ń dènà (àwọn ènìyàn) kúrò ní Ọ̀nà Allah. 8:47
- Allah kì í yí ọ̀pẹ tí Ó ti fi fún àwọn ènìyàn padà títí wọn yóò fi yí ohun tí ó wà nínú ara wọn padà. 8:53
- Àwọn ẹ̀dá tí ó burú jù lọ ní ọ̀dọ̀ Allah ni àwọn aláìgbàgbọ́. 8:55
- Ọlọ́run ń fi ìfẹ́ àti ìfọkànsí sí àwọn ọkàn tí ó bá gbàgbọ́ nínú Rẹ̀ 8:63
- Ẹ máa dáàbò bo àwọn tí ó ń wá ààbò, kí ẹ sì máa ràn wọn lọ́wọ́ 9:6
- Kò tọ́ fún àwọn alápọ̀wé (Mushrikun) láti máa bójútó àwọn ilé mọ́sálásí Allah. 9:17
- Àwọn (aláìgbàgbọ́, àwọn Júù àti àwọn Kristian) fẹ́ pa Ìmọ́lẹ̀ Allah (tí a fi rán Muhammad ﷺ – Ẹ̀sìn ìbọ̀kan-ṣoṣo Islam) pẹ̀lú ẹnu wọn, ṹ̀gbọ́n Allah kò gbà àyàfi pé kí Ìmọ́lẹ̀ Rẹ̀ parí, bí ó tilẹ̀ jẹ́ pé àwọn aláìgbàgbọ́ kórìíra rẹ̀. 9:32
- Sadaqah (ìyẹn Zakat) jẹ́ ti àwọn wọ̀nyí nìkan: 1) àwọn òtòṣì, 2) àwọn aláìní, 3) àwọn tí a gbàwé láti ṣàjọpín rẹ̀, 4) láti fàwọn tí wọ́n rọ̀ mọ́ Islam, 5) láti dá àwọn ẹrú sílẹ̀, 6) fún àwọn onígbèsè, 7) ní Ọ̀nà Allah (ìyẹn fún àwọn Mujahidun), àti 8) fún arìnrìn-àjò. 9:60
- Ẹnikẹ́ni tí ó bá tako tí ó sì ń ṣe ọ̀tá sí Allah àti Ojúṣe Rẹ̀ (ﷺ), dájúdájú iná ọ̀run àpáàdì ni tìrẹ̀, yóò sì máa gbé ibẹ̀ láé. Ìyẹn ni ìtìjú ńlá. 9:63
- Àwọn agàbàgebè, ọkùnrin àti obìnrin, wọn jọra wọn. Wọn ti gbàgbé Allah, nítorí náà Òun sì ti gbàgbé wọn. 9:67
- Ẹ máa sapá fún mímọ́. Ẹ máa bọ̀wọ̀ fún mímọ́ ilé mọ́sálásí 9:108
- Kò tọ́ fún Ànábì àti àwọn onígbàgbọ́ láti máa bẹ̀bẹ̀ fún ìdáríjì lọ́dọ̀ Allah fún àwọn alápọ̀wé, bí ó tilẹ̀ jẹ́ pé wọ́n jẹ́ ìbátan, lẹ́yìn tí ó ti kédè fún wọn pé wọn jẹ́ àwọn ará Iná (nítorí wọ́n kú nígbà tí wọn kò gbàgbọ́). 9:113
- Ta ni ó ṣe búburú ju ẹni tí ó dake èké sí Allah, tàbí ẹni tí ó kọ àwọn Ẹsẹ Rẹ̀? Dájúdájú, àwọn ẹlẹ́ṣẹ̀ kò ní ṣàṣeyọrí! 10:17
- Wọ́n ń jọ́sìn lẹ́yìn Allah àwọn ohun tí kò lè ṣe wọn láàánú tàbí kí wọn ṣe wọn lánfààní, wọ́n sì ń sọ pé: "Àwọn wọ̀nyí ni àwọn alágbèjáwọ wa ní ọ̀dọ̀ Allah." Sọ: "Ṣé ẹ̀yin ń sọ fún Allah ohun tí Kò mọ̀ ní àwọn ọ̀run àti ní ilẹ̀?" Ògo ni fún Un, Ó sì ga jù ohun tí wọn ń fi ṣe alábàápín fún Un lọ! 10:18
- Ẹ̀san iṣẹ́ búburú ni irú rẹ̀. 10:27
- Ọlọ́hun náà ni Allah, Olúwa yín tí ó jẹ́ òtítọ́. Nítorí náà, lẹ́yìn òtítọ́, ohun mìíràn àfi àṣìṣe ni kù? Nígbà náà, báwo ni a ṣe ń yí yín padà? 10:32
- Ọ̀pọ̀ wọn kò tẹ̀lé ohunkóhun bí kò ṣe ìrò. Dájúdájú, ìrò kò lè rópo òtítọ́. 10:36
- Dájúdájú, Allah kò ṣe àìṣòdodo sí àwọn ènìyàn ní ohunkóhun, ṹ̀gbọ́n àwọn ènìyàn ń ṣe àìṣòdodo sí ara wọn. 10:44
- Ẹ mọ̀ pé ǹkan jẹ́ tí Ọlọ́run tó dára ju ohunkóhun tí ènìyàn lè kó jọ tàbí tí ó lè ṣàǹfààní lọ 10:58
- Ẹ má ṣe jẹ́ ọ̀kan nínú àwọn tí ń kọ àwọn Ẹsẹ Allah, nítorí nígbà náà ẹ yóò jẹ́ ọ̀kan nínú àwọn olùdánù. 10:95
- Bí Allah bá fi ìpọ́njú kàn yín, kò sí ẹni tí lè yọ́ ọn kúrò bí kò ṣe Òun; bí Ó bá sì fẹ́ ohun rere fún yín, kò sí ẹni tí lè tan Ojú-rere Rẹ̀ padà, tí Ó ń jẹ́ kí ó dé bá ẹni tí Ó fẹ́ nínú àwọn iranṣẹ́ Rẹ̀. 10:107
- Kò sí ẹ̀dá tí ń la lórí ilẹ̀ tí oúnjẹ rẹ̀ kò bá jẹ́ ti Allah. Òun sì mọ ibi tí ó ń gbé àti ibi tí a ó gbé palẹ̀ (nínú rẹ̀) (nínú ilẹ̀). 11:6
- Bí a bá fi àánú kan láti ọ̀dọ̀ Wa tọ́ ọ wá, a sì yọ́ ọn kúrò lọ́dọ̀ rẹ̀, dájúdájú! Ó máa sọ̀rẹ̀, ó sì ń ṣe aláìmoore. 11:9
- Ẹnikẹ́ni tí ó bá fẹ́ ayé yi àti ọ̀ṣọ́ rẹ̀, A ó fún wọn ní kíkún ẹ̀san iṣẹ́ wọn nínú rẹ̀, wọn kò sì ní dín kù. 11:15
- A kò ṣe àìṣòdodo sí wọn, ṹ̀gbọ́n wọn ló ṣe àìṣòdodo sí ara wọn. Nítorí náà, àwọn òrìṣà wọn tí wọn ń pe lẹ́yìn Allah, kò ṣe wọn lánfààní ní ohunkóhun nígbà tí àṣẹ Olúwa yín dé, wọn kò sì fi ohunkóhun kún wọn bí kò ṣe ìparun. 11:101
- Ní Ọjọ́ tí yóò dé, kò sí ẹni tí yóò sọ̀rọ̀ àyàfi pẹ̀lú ìyọ̀nda Rẹ̀. Àwọn kan nínú wọn yóò jẹ́ aláìníláárí àti (àwọn kan) Ọlọ́lá. 11:105
- Fún àwọn aláìníláárí, wọn yóò wà nínú Iná, wọn yóò máa kígbe àti máa kù ín. 11:106
- Wọn yóò máa gbé ibẹ̀ ní gbogbo ìgbà tí àwọn ọ̀run àti ilẹ̀ bá ń bẹ, àyàfi bí Olúwa yín bá fẹ́. Dájúdájú, Olúwa yín ń ṣe ohun tí Ó bá fẹ́. 11:107
- Àwọn Ọlọ́lá yóò wà nínú Ọ̀run, wọn yóò máa gbé ibẹ̀ ní gbogbo ìgbà tí àwọn ọ̀run àti ilẹ̀ bá ń bẹ, àyàfi bí Olúwa yín bá fẹ́, gẹ́gẹ́ bí ẹ̀bùn tí kò lópin. 11:108
- Ẹ má ṣe tọ̀ sí àwọn tí ń ṣe àìṣòdodo, kí Iná má bá à fọwọ́ kan yín, kí ẹ sì má ní àwọn alábojútó yàtọ̀ sí Allah, bẹ́ẹ̀ ni ẹ kì yóò ní ìrànlọ́wọ́. 11:113
- Ẹ máa ṣe àdúrà ní àwọn òpin méjèèjì ọjọ́ àti ní àwọn wákàtí alẹ́ (ìyẹn àdúrà márùn-ún ojoojúmọ́). Àwọn iṣẹ́ rere ń pa àwọn iṣẹ́ búburú (àwọn ẹ̀ṣẹ̀ kéékèké) kúrò. 11:114
- Ti Allah ni ohun ìkọ̀kọ̀ àwọn ọ̀run àti ilẹ̀, sí Òun ni a ó sì dá gbogbo ọ̀ràn padà (fún ìpinnu). 11:123
- Àṣẹ (tàbí ìpinnu) jẹ́ ti Allah nìkan. Ó ti pa láṣẹ pé kí ẹ má ṣe jọ́sìn ẹnikẹ́ni bí kò ṣe Òun (ìbọ̀kan-ṣoṣo Rẹ̀), ìyẹn ni ẹ̀sìn tààrà, ṹ̀gbọ́n ọ̀pọ̀ ènìyàn kò mọ̀. 12:40
- Ẹ má ṣe pàdánù ìrètí nínú Àánú Allah 12:87
- Ọ̀pọ̀ ènìyàn kò ní gbàgbọ́, bí ó tilẹ̀ jẹ́ pé ẹ ń fẹ́ rẹ̀. 12:103
- Ọ̀pọ̀ wọn kò gbàgbọ́ nínú Allah àyàfi pé wọn ń ṣe alábàápín fún Un (ìyẹn wọn jẹ́ alápọ̀wé). 12:106
- (Al-Ƙur’ān) kì í ṣe ọ̀rọ̀ àròsọ, ṹ̀gbọ́n ó jẹ́ ìdúróṣánṣán fún àwọn Ìwé Mímọ́ tí ó ti wà tẹ́lẹ̀ (Tawrat, Injil àti àwọn Ìwé Mímọ́ mìíràn) àti àlàyé kúlẹ̀kúlẹ̀ ohun gbogbo, àti ìtọ́sọ́nà àti àánú fún àwọn ènìyàn tí ó gbàgbọ́. 12:111
- Allah ń pọ̀ṣe oúnjẹ fún ẹni tí Ó bá fẹ́, Ó sì ń dín kù (fún ẹni tí Ó bá fẹ́). 13:26
- Ẹ máa rántí Allah ní gbogbo ìgbà nípa dhikr. Àwọn tí ó gbàgbọ́ nínú Ọlọ́run ń rí ìtẹ́lọ́rùn nínú rírántí Rẹ̀. 13:28
- Àwọn tí ó gbàgbọ́ tí wọ́n sì ń ṣe iṣẹ́ rere, wọn yóò jẹ́ onídùnnú àti ọkàn-ọ̀fẹ́. 13:29
- Àwọn tí ó fẹ́ ayé yìí ju Ọ̀run lọ, tí wọn sì ń dènà (àwọn ènìyàn) kúrò ní Ọ̀nà Allah (Islam), tí wọn sì ń wá ìwọ̀n-ọ̀nà nínú rẹ̀ – àwọn wọ̀nyí wà nínú àṣìṣe tí ó jìnnà. 14:3
- Ẹ máa fi ìrẹ̀lẹ̀ àti ìmoore hàn nínú ìjọsìn 14:7
- Àpẹẹrẹ àwọn tí kò gbàgbọ́ nínú Olúwa wọn ni pé àwọn iṣẹ́ wọn dàbí eérú, tí ẹ̀fúùfù ń fẹ́ lórí rẹ̀ ní ọjọ́ ìjì, wọn kò ní lè gba ohunkóhun nínú ohun tí wọ́n ṣiṣẹ́. 14:18
- Allah yóò fẹsẹ̀ múlẹ̀ fún àwọn tí ó gbàgbọ́, pẹ̀lú ọ̀rọ̀ tí ó dúró ṣinṣin nínú ayé yìí (ìyẹn wọn yóò máa jọ́sìn Allah nìkan) àti ní Ọ̀run. 14:27
- Ẹ má ṣe rò pé Allah kò mọ ohun tí àwọn aláìṣòdodo (àwọn alápọ̀wé, àwọn oníwà búburú, àti bẹ́ẹ̀ bẹ́ẹ̀ lọ) ń ṣe, ṹ̀gbọ́n Ó ń gbà wọn ní àkókò sí Ọjọ́ tí àwọn ojú yóò máa tẹ̀jú mọ́. 14:42
- Kí Allah lè san ẹ̀san fún ẹ̀mí kọ̀ọ̀kan gẹ́gẹ́ bí ohun tí ó ṣiṣẹ́. Dájúdájú, Allah ń yára ṣe ìṣirò. 14:51
- Dájúdájú, A dá ènìyàn láti inú amọ̀ tí ń dún, láti inú ẹrẹ̀ dúdú tí a ṣe bí àwo. 15:26
- Àwọn jinn, A dá wọn ṣáájú láti inú iná tí kò ní ẹ̀fin. 15:27
- Ó ní ẹnu-ọ̀nà méje, ẹnu-ọ̀nà kọ̀ọ̀kan ni a ti pín sí (pàtàkì) ẹ̀ka (àwọn ẹlẹ́ṣẹ̀). 15:44
- Ó dá ènìyàn láti inú Nutfah (ìṣu omi tí a dàpọ̀), lẹ́yìn náà, kíyèsi i, ènìyàn yìí di ọ̀tá gbangba. 16:4
- Àwọn ẹran ọ̀sìn, Ó dá wọn fún yín; nínú wọn ni ẹ̀wù gbígbóná, àti ọ̀pọ̀lọpọ̀ àǹfààní, látinú wọn ni ẹ sì ń jẹ. 16:5
- (Ó sì dá) ẹṣin, ìbàkà àti kẹ́tẹ́kẹ́tẹ́, fún gígun àti fún ọ̀ṣọ́. Ó sì ń dá àwọn ohun mìíràn tí ẹ kò mọ̀. 16:8
- Òun ni Ẹni tí ń rọ̀ omi (òjò) láti ọ̀run wá; nínú rẹ̀ ni ẹ ń mu, láti inú rẹ̀ ni ewéko tí ẹ ń jẹ àwọn ẹran ọ̀sìn yín. 16:10
- Òun ni Ẹni tí ó tẹ́ okun lọ́wọ́ fún yín, kí ẹ lè jẹ ẹran tuntun (ẹja) láti inú rẹ̀, kí ẹ sì lè mú àwọn ohun ọ̀ṣọ́ tí ẹ ń wọ̀ jáde láti inú rẹ̀. 16:14
- Ó fi àwọn òkè ńlá gbọn-in gbọn-in sí ilẹ̀, kí ilẹ̀ má bá à gbọn pẹ̀lú yín, àti àwọn odò àti àwọn ọ̀nà, kí ẹ lè rí ọ̀nà. 16:15
